module IceMazeSolver #(\n    parameter ROWS = 4,\n    parameter COLS = 4,\n    parameter CELL_COUNT = ROWS * COLS,\n    parameter DATA_WIDTH = 2,\n    parameter DIST_WIDTH = 5,\n    parameter DIR_COUNT = 4,\n    parameter MAX_CYCLES = 256\n)(\n    input clk,\n    input rst_n,\n    input start,\n    input [CELL_COUNT*DATA_WIDTH-1:0] grid_data,\n    output reg [CELL_COUNT*DIST_WIDTH-1:0] distances_data,\n    output reg done\n);\n    // State encoding\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] SETUP = 3'd1;\n    localparam [2:0] CHECK_CELL = 3'd2;\n    localparam [2:0] CALC_SLIDE = 3'd3;\n    localparam [2:0] UPDATE = 3'd4;\n    localparam [2:0] NEXT_DIR = 3'd5;\n    localparam [2:0] NEXT_CELL = 3'd6;\n    localparam [2:0] FINISHED = 3'd7;\n    reg [2:0] state;\n    reg [2:0] next_state;\n    \n    // Grid and distance storage\n    reg [DATA_WIDTH-1:0] grid [0:CELL_COUNT-1];\n    reg [DIST_WIDTH-1:0] dist [0:CELL_COUNT-1];\n    reg [DIST_WIDTH-1:0] next_dist [0:CELL_COUNT-1];\n    \n    // Current cell and direction\n    reg [5:0] curr_cell;\n    reg [1:0] curr_dir;\n    reg [7:0] cycle_count;\n    \n    // Slide computation\n    reg [3:0] slide_r;\n    reg [3:0] slide_c;\n    reg [3:0] next_r;\n    reg [3:0] next_c;\n    reg [5:0] target_idx;\n    reg slide_active;\n    reg slide_done;\n    \n    // Unpack grid_data into array\n    integer i;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            for (i = 0; i < CELL_COUNT; i = i + 1) begin\n                grid[i] <= 2'd0;\n            end\n        end else begin\n            for (i = 0; i < CELL_COUNT; i = i + 1) begin\n                grid[i] <= grid_data[i*DATA_WIDTH +: DATA_WIDTH];\n            end\n        end\n    end\n    \n    // Helper: convert linear index to coordinates\n    function automatic [3:0] idx_to_coord;\n        input [5:0] idx;\n        begin\n            idx_to_coord = idx / COLS;\n        end\n    endfunction\n    \n    function automatic [3:0] idx_to_col;\n        input [5:0] idx;\n        begin\n            idx_to_col = idx % COLS;\n        end\n    endfunction\n    \n    // Helper: convert coordinates to linear index\n    function automatic [5:0] coord_to_idx;\n        input [3:0] r, c;\n        begin\n            coord_to_idx = r * COLS + c;\n        end\n    endfunction\n    \n    // Slide computation combinational logic\n    always @(*) begin\n        slide_done = 1'b0;\n        next_r = slide_r;\n        next_c = slide_c;\n        target_idx = coord_to_idx(slide_r, slide_c);\n        \n        if (slide_active) begin\n            // Calculate next position based on direction\n            case (curr_dir)\n                2'b00: next_r = slide_r - 1; // up\n                2'b01: next_r = slide_r + 1; // down\n                2'b10: next_c = slide_c - 1; // left\n                2'b11: next_c = slide_c + 1; // right\n            endcase\n            \n            // Check boundaries\n            if (next_r >= ROWS || next_c >= COLS) begin\n                slide_done = 1'b1;\n            end else begin\n                // Check cell type\n                case (grid[coord_to_idx(next_r, next_c)])\n                    2'b00: slide_done = 1'b1; // obstacle\n                    2'b01, 2'b11: begin // gravel or goal\n                        target_idx = coord_to_idx(next_r, next_c);\n                        slide_done = 1'b1;\n                    end\n                    2'b10: begin // ice - continue sliding\n                        // Update for next iteration\n                        slide_r = next_r;\n                        slide_c = next_c;\n                        slide_done = 1'b0;\n                    end\n                    default: slide_done = 1'b1;\n                endcase\n            end\n        end\n    end\n    \n    // State machine and distance updates\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            cycle_count <= 8'd0;\n            slide_active <= 1'b0;\n            // Reset distances to INF (31)\n            for (i = 0; i < CELL_COUNT; i = i + 1) begin\n                dist[i] <= 5'd31;\n                next_dist[i] <= 5'd31;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        state <= SETUP;\n                        done <= 1'b0;\n                    end\n                end\n                SETUP: begin\n                    // Find goal and set distance to 0\n                    for (i = 0; i < CELL_COUNT; i = i + 1) begin\n                        if (grid[i] == 2'b11) begin\n                            dist[i] <= 5'd0;\n                            next_dist[i] <= 5'd0;\n                        end else begin\n                            dist[i] <= 5'd31;\n                            next_dist[i] <= 5'd31;\n                        end\n                    end\n                    curr_cell <= 6'd0;\n                    curr_dir <= 2'd0;\n                    cycle_count <= 8'd0;\n                    state <= CHECK_CELL;\n                end\n                CHECK_CELL: begin\n                    if (curr_cell < CELL_COUNT && cycle_count < MAX_CYCLES) begin\n                        if (dist[curr_cell] != 5'd31) begin\n                            // Calculate starting position for slide\n                            slide_r <= idx_to_coord(curr_cell);\n                            slide_c <= idx_to_col(curr_cell);\n                            slide_active <= 1'b1;\n                            state <= CALC_SLIDE;\n                        end else begin\n                            state <= NEXT_CELL;\n                        end\n                    end else begin\n                        state <= FINISHED;\n                    end\n                end\n                CALC_SLIDE: begin\n                    if (slide_done) begin\n                        slide_active <= 1'b0;\n                        state <= UPDATE;\n                    end\n                end\n                UPDATE: begin\n                    if (target_idx != curr_cell && target_idx < CELL_COUNT) begin\n                        // Update distance using reverse edge: dist[target] = min(dist[target], dist[curr] + 1)\n                        if (next_dist[target_idx] > dist[curr_cell] + 1) begin\n                            next_dist[target_idx] <= dist[curr_cell] + 1;\n                        end\n                    end\n                    state <= NEXT_DIR;\n                end\n                NEXT_DIR: begin\n                    if (curr_dir < DIR_COUNT - 1) begin\n                        curr_dir <= curr_dir + 1;\n                        state <= CHECK_CELL;\n                    end else begin\n                        state <= NEXT_CELL;\n                    end\n                end\n                NEXT_CELL: begin\n                    curr_cell <= curr_cell + 1;\n                    curr_dir <= 2'd0;\n                    cycle_count <= cycle_count + 1;\n                    // Update all distances at end of iteration\n                    for (i = 0; i < CELL_COUNT; i = i + 1) begin\n                        dist[i] <= next_dist[i];\n                    end\n                    state <= CHECK_CELL;\n                end\n                FINISHED: begin\n                    // Pack distances into output\n                    for (i = 0; i < CELL_COUNT; i = i + 1) begin\n                        distances_data[i*DIST_WIDTH +: DIST_WIDTH] <= dist[i];\n                    end\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule